//! Expected expansions; times are written in the series' own offset.

use super::*;

fn instances(
    rule: &str,
    zone: &str,
    wall: (i16, i8, i8, i8, i8, i8),
    take: usize,
) -> Option<Vec<String>> {
    let zone = solstone_core_time::zone(zone).unwrap();
    let wall = jiff::civil::date(wall.0, wall.1, wall.2).at(wall.3, wall.4, wall.5, 0);
    let start = solstone_core_time::from_local(&zone, wall)
        .earliest()
        .unwrap();
    let recurrence = Rule::parse(rule).ok()?.build(&start).ok()?;
    Some(
        recurrence
            .iter()
            .take(take)
            .map(|time| {
                solstone_core_time::zoned_rfc3339(&time, solstone_core_time::Precision::Secs, false)
            })
            .collect(),
    )
}

