#[test]
fn each_rule_expands_as_recorded() {
    for (rule, zone, wall, take, expected) in CASES {
        let expected = expected.map(|list| {
            list.iter()
                .map(|item| (*item).to_owned())
                .collect::<Vec<_>>()
        });
        assert_eq!(
            instances(rule, zone, *wall, *take),
            expected,
            "{rule} from {wall:?} in {zone}"
        );
    }
}

#[test]
fn an_until_given_as_an_instant_replaces_the_rules_own() {
    let zone = solstone_core_time::zone("America/Denver").unwrap();
    let start =
        solstone_core_time::from_local(&zone, jiff::civil::date(2026, 10, 27).at(9, 0, 0, 0))
            .single()
            .unwrap();
    let until: jiff::Timestamp = "2026-11-10T16:00:00Z".parse().unwrap();
    let rule = Rule::parse("FREQ=WEEKLY").unwrap().until(until);
    let written: Vec<_> = rule
        .build(&start)
        .unwrap()
        .iter()
        .map(|time| {
            solstone_core_time::zoned_rfc3339(&time, solstone_core_time::Precision::Secs, false)
        })
        .collect();
    assert_eq!(
        written,
        [
            "2026-10-27T09:00:00-06:00",
            "2026-11-03T09:00:00-07:00",
            "2026-11-10T09:00:00-07:00"
        ]
    );
    let before: jiff::Timestamp = "2026-10-27T14:59:59Z".parse().unwrap();
    assert!(
        Rule::parse("FREQ=WEEKLY")
            .unwrap()
            .until(before)
            .build(&start)
            .is_err()
    );
}

#[test]
fn a_rule_that_never_picks_ends_instead_of_stepping_on() {
    let start = jiff::Timestamp::UNIX_EPOCH.to_zoned_datetime(jiff::tz::TimeZone::UTC);
    let recurrence = Rule::parse("FREQ=HOURLY;BYSETPOS=2")
        .unwrap()
        .build(&start)
        .unwrap();
    assert_eq!(recurrence.iter().next(), None);
}
